"use client";

import { useMemo, useState } from "react";
import { Download } from "lucide-react";
import { RoleRouteGuard } from "@/compartido/components/role/role-route-guard";
import { apiRequest } from "@/compartido/lib/api";
import { useAuthUser } from "@/compartido/hooks/use-auth-user";
import { useVacancyTheme } from "@/compartido/theme/use-vacancy-theme";
import { AdminDashboardShell } from "@/frontend/admin/components/system/admin-dashboard-shell";
import { useAdminConsole } from "@/frontend/admin/hooks/use-admin-console";
import {
  AdminGhostButton,
  AdminPill,
  AdminSectionHeading,
  AdminSimpleTable,
  AdminStatCard,
  AdminSurface,
} from "@/frontend/admin/components/system/admin-dashboard-kit";
import type { AdminConsolePayload } from "@/compartido/types/admin";

const PAGE_SIZE = 20;
const MAX_PAGES = 10;

function buildIsoRange(value: string, endOfDay = false) {
  if (!value) {
    return "";
  }

  const suffix = endOfDay ? "T23:59:59.999" : "T00:00:00.000";
  return new Date(`${value}${suffix}`).toISOString();
}

function escapeCsv(value: unknown) {
  const normalized = String(value ?? "");
  if (normalized.includes(",") || normalized.includes("\"") || normalized.includes("\n")) {
    return `"${normalized.replace(/"/g, "\"\"")}"`;
  }

  return normalized;
}

export default function AdminTasksPage() {
  const { isDark, toggleTheme } = useVacancyTheme();
  const { authUser } = useAuthUser();
  const enabled = authUser?.role === "admin";
  const consoleQuery = useMemo(() => ({ activityType: "api_request", activityLimit: PAGE_SIZE * MAX_PAGES }), []);
  const { consoleData } = useAdminConsole(enabled, 10_000, consoleQuery);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [notice, setNotice] = useState<string | null>(null);
  const [exporting, setExporting] = useState(false);

  const requestActivities = useMemo(
    () => (consoleData?.activities ?? []).filter((activity) => activity.type === "api_request"),
    [consoleData?.activities],
  );
  const totalPages = Math.max(1, Math.min(MAX_PAGES, Math.ceil(requestActivities.length / PAGE_SIZE)));
  const visiblePage = Math.min(currentPage, totalPages);
  const latestRequests = requestActivities.slice((visiblePage - 1) * PAGE_SIZE, visiblePage * PAGE_SIZE);
  const failingRequests = requestActivities.filter((activity) => (activity.statusCode ?? 0) >= 400).length;
  const latestDuration = requestActivities[0]?.durationMs ?? 0;

  const exportCsv = async () => {
    setExporting(true);
    setNotice(null);

    const from = buildIsoRange(startDate);
    const to = buildIsoRange(endDate, true);
    const params = new URLSearchParams({
      activityType: "api_request",
      activityLimit: "1000",
    });

    if (from) {
      params.set("from", from);
    }
    if (to) {
      params.set("to", to);
    }

    const response = await apiRequest<AdminConsolePayload>(`/api/admin/console?${params.toString()}`);
    if (!response.ok || !response.data) {
      setExporting(false);
      setNotice("No se pudieron exportar los registros.");
      return;
    }

    const rows = (response.data.activities ?? []).filter((activity) => activity.type === "api_request");
    const csvLines = [
      ["timestamp", "method", "request_path", "status_code", "duration_ms", "actor_role", "page_path", "source"].join(","),
      ...rows.map((activity) => [
        escapeCsv(activity.happenedAt),
        escapeCsv(activity.method ?? ""),
        escapeCsv(activity.targetPath ?? activity.entityId),
        escapeCsv(activity.statusCode ?? ""),
        escapeCsv(activity.durationMs ?? ""),
        escapeCsv(activity.actorRole ?? ""),
        escapeCsv(activity.pathname ?? ""),
        escapeCsv(activity.source ?? ""),
      ].join(",")),
    ];

    const blob = new Blob([csvLines.join("\n")], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `admin-api-monitor-${Date.now()}.csv`;
    link.click();
    URL.revokeObjectURL(url);

    setExporting(false);
    setNotice(`${rows.length} registros exportados a CSV.`);
  };

  return (
    <RoleRouteGuard allowedRole="admin">
      <AdminDashboardShell
        isDark={isDark}
        onToggleTheme={toggleTheme}
        title="Tasks"
        description="Real-time API monitor. Refreshes every 10 seconds and shows 20 requests per page up to 10 pages."
        actions={
          <AdminGhostButton isDark={isDark} disabled={exporting} onClick={() => void exportCsv()}>
            <Download className="h-4 w-4" />
            {exporting ? "Exporting..." : "Export CSV"}
          </AdminGhostButton>
        }
      >
        {notice ? (
          <div className={isDark ? "rounded-2xl border border-cyan-300/18 bg-cyan-300/8 px-4 py-3 text-sm text-cyan-100" : "rounded-2xl border border-sky-300 bg-sky-50 px-4 py-3 text-sm text-sky-700"}>
            {notice}
          </div>
        ) : null}

        <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
          <AdminStatCard isDark={isDark} icon={Download} label="Current Page" value={latestRequests.length} helper="20 requests per page." />
          <AdminStatCard isDark={isDark} icon={Download} label="Tracked Requests" value={requestActivities.length} helper="Current in-memory admin window." />
          <AdminStatCard isDark={isDark} icon={Download} label="Failing Requests" value={failingRequests} helper="Status code >= 400 within the latest window." />
          <AdminStatCard isDark={isDark} icon={Download} label="Last Duration" value={`${latestDuration} ms`} helper="Duration of the newest recorded request." />
        </section>

        <AdminSurface isDark={isDark}>
          <AdminSectionHeading
            isDark={isDark}
            title="Export Range"
            description="Generate a CSV from monitored API records between start and end dates."
          />
          <div className="mt-5 flex flex-wrap gap-3">
            <label className={isDark ? "flex min-w-[16rem] flex-col gap-2 text-sm text-slate-200" : "flex min-w-[16rem] flex-col gap-2 text-sm text-slate-700"}>
              Start date
              <input
                type="date"
                value={startDate}
                onChange={(event) => setStartDate(event.target.value)}
                className="rounded-2xl border border-slate-300 bg-white px-4 py-2.5 text-sm text-slate-900 outline-none"
              />
            </label>
            <label className={isDark ? "flex min-w-[16rem] flex-col gap-2 text-sm text-slate-200" : "flex min-w-[16rem] flex-col gap-2 text-sm text-slate-700"}>
              End date
              <input
                type="date"
                value={endDate}
                onChange={(event) => setEndDate(event.target.value)}
                className="rounded-2xl border border-slate-300 bg-white px-4 py-2.5 text-sm text-slate-900 outline-none"
              />
            </label>
          </div>
        </AdminSurface>

        <AdminSimpleTable isDark={isDark}>
          <table className="w-full min-w-[980px] text-sm">
            <thead className={isDark ? "border-b border-white/8 bg-white/[0.03] text-slate-400" : "border-b border-slate-200 bg-slate-50 text-slate-500"}>
              <tr>
                <th className="px-4 py-3 text-left font-medium">When</th>
                <th className="px-4 py-3 text-left font-medium">Method</th>
                <th className="px-4 py-3 text-left font-medium">Request</th>
                <th className="px-4 py-3 text-left font-medium">Status</th>
                <th className="px-4 py-3 text-left font-medium">Duration</th>
                <th className="px-4 py-3 text-left font-medium">Actor</th>
              </tr>
            </thead>
            <tbody>
              {latestRequests.map((activity) => (
                <tr key={activity.id} className={isDark ? "border-b border-white/6 last:border-b-0" : "border-b border-slate-100 last:border-b-0"}>
                  <td className="px-4 py-4 align-top">{new Date(activity.happenedAt).toLocaleString("es-CO")}</td>
                  <td className="px-4 py-4 align-top">
                    <AdminPill isDark={isDark}>{activity.method ?? "GET"}</AdminPill>
                  </td>
                  <td className="px-4 py-4 align-top">
                    <div>
                      <p className={isDark ? "font-medium text-white" : "font-medium text-slate-950"}>{activity.targetPath ?? activity.entityId}</p>
                      <p className={isDark ? "mt-1 text-xs text-slate-500" : "mt-1 text-xs text-slate-500"}>{activity.pathname ?? "no-page-context"}</p>
                    </div>
                  </td>
                  <td className="px-4 py-4 align-top">
                    <AdminPill isDark={isDark} tone={(activity.statusCode ?? 0) >= 400 ? "danger" : "success"}>
                      {activity.statusCode ?? 0}
                    </AdminPill>
                  </td>
                  <td className="px-4 py-4 align-top">{activity.durationMs ?? 0} ms</td>
                  <td className="px-4 py-4 align-top">{activity.actorRole ?? "anonymous"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </AdminSimpleTable>

        <div className="flex flex-wrap items-center justify-center gap-2">
          {Array.from({ length: totalPages }, (_, index) => index + 1).map((pageNumber) => {
            const active = pageNumber === visiblePage;
            return (
              <button
                key={pageNumber}
                type="button"
                onClick={() => setCurrentPage(pageNumber)}
                className={
                  active
                    ? isDark
                      ? "h-10 w-10 scale-110 rounded-full bg-violet-300 text-sm font-bold text-violet-950 shadow-[0_0_0_4px_rgba(196,181,253,0.22)]"
                      : "h-10 w-10 scale-110 rounded-full bg-white text-sm font-bold text-slate-950 shadow-[0_0_0_4px_rgba(255,255,255,0.95),0_8px_24px_rgba(15,23,42,0.16)]"
                    : isDark
                      ? "h-9 w-9 rounded-full border border-white/10 bg-white/5 text-sm font-semibold text-slate-300 transition hover:bg-white/10"
                      : "h-9 w-9 rounded-full border border-slate-300 bg-slate-50 text-sm font-semibold text-slate-700 transition hover:bg-white"
                }
                aria-current={active ? "page" : undefined}
              >
                {pageNumber}
              </button>
            );
          })}
        </div>
      </AdminDashboardShell>
    </RoleRouteGuard>
  );
}
